package com.google.javascript.jscomp;

import junit.framework.TestCase;

public class TypeCheckAI2Test extends TestCase {

  private Compiler compiler;

  @Override
  protected void setUp() throws Exception {
    super.setUp();
    compiler = new Compiler();
  }

  public void testBitOperationTypeCheck() {
    CompilerOptions options = new CompilerOptions();
    options.checkTypes = true;
    compiler.initOptions(options);

    JSSourceFile externs = JSSourceFile.fromCode("externs.js", "var undefined;");
    JSSourceFile input = JSSourceFile.fromCode("input.js", "var x = 'hello' << 2;");

    Result result = compiler.compile(externs, new JSSourceFile[] { input }, options);
    assertFalse(result.success);
    assertTrue(result.errors.length > 0);
  }

  public void testValidArithmeticTypeCheck() {
    CompilerOptions options = new CompilerOptions();
    options.checkTypes = true;
    compiler.initOptions(options);

    JSSourceFile externs = JSSourceFile.fromCode("externs.js", "var undefined;");
    JSSourceFile input = JSSourceFile.fromCode("input.js", "var x = 10 - 2;");

    Result result = compiler.compile(externs, new JSSourceFile[] { input }, options);
    assertTrue(result.success);
    assertEquals(0, result.errors.length);
  }

  public void testInvalidArithmeticTypeCheck() {
    CompilerOptions options = new CompilerOptions();
    options.checkTypes = true;
    compiler.initOptions(options);

    JSSourceFile externs = JSSourceFile.fromCode("externs.js", "var undefined;");
    JSSourceFile input = JSSourceFile.fromCode("input.js", "var x = 'abc' - 2;");

    Result result = compiler.compile(externs, new JSSourceFile[] { input }, options);
    assertFalse(result.success);
    assertTrue(result.errors.length > 0);
  }
}
